const inp = $input.first().json || {};
const inicio = String(inp.inicio_iso || '').trim();
const fin = String(inp.fin_iso || '').trim();
const contacto = String(inp.numero_contacto || '').replace(/\D/g, '');
const nombre = String(inp.nombre_contacto || 'Lead IA360').trim();
const wa = String(inp.wa_number || '').replace(/\D/g, '');
const sourceMsgId = String(inp.source_message_id || '').trim();
const titulo = String(inp.titulo || '').trim() || (`Reunión IA360 - ${nombre}`);
const dryRun = Boolean(inp.dry_run);

if (!inicio || !fin) {
  throw new Error('FALTAN_HORARIOS: inicio_iso y fin_iso son obligatorios en formato ISO 8601 UTC.');
}
if (!contacto) {
  throw new Error('FALTA_CONTACTO: numero_contacto es obligatorio para generar la propuesta.');
}

const payload = {
  wa_number: wa || null,
  contact_number: contacto,
  source_message_id: sourceMsgId || null,
  kind: 'book',
  start_utc: inicio,
  end_utc: fin,
  title: titulo,
  dry_run: dryRun
};

return [{ json: payload }];

const resp = $input.first().json || {};
const prep = $('Preparar Propuesta Reserva').first().json || {};
const ok = resp.ok === true;
const proposalId = resp.proposal_id || null;
const state = resp.state || (ok ? 'pending_owner_confirmation' : 'blocked');
const msg = resp.message || (ok
  ? `Propuesta de reunión generada (${prep.start_utc} a ${prep.end_utc}) y enviada a Alek para confirmación.`
  : `No se pudo generar la propuesta de reunión: ${resp.error || 'error desconocido'}`);

return [{
  json: {
    ok,
    estado: ok ? 'propuesta_creada' : 'error_propuesta',
    state,
    proposal_id: proposalId,
    start_utc: prep.start_utc,
    end_utc: prep.end_utc,
    titulo: prep.title,
    mensaje: msg,
    requires_owner_tap: ok && state === 'pending_owner_confirmation'
  }
}];

const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: agenda local requiere bearer token valido de N8N_CALENDAR_TOKEN');
}

const inp = raw.body || raw;
const confirmado = String(inp.confirmado_por_owner || '').toLowerCase() === 'true';
if (!confirmado) {
  throw new Error('CONFIRMACION_REQUERIDA: agendar escribe en el calendario real de Alek. Requiere confirmacion del owner.');
}

const inicio = String(inp.inicio_iso || '').trim();
const fin = String(inp.fin_iso || '').trim();
if (!inicio || !fin) throw new Error('FALTAN_HORARIOS: inicio_iso y fin_iso son obligatorios en ISO 8601 UTC.');
if (Number.isNaN(Date.parse(inicio)) || Number.isNaN(Date.parse(fin))) throw new Error('HORARIO_INVALIDO: usa ISO 8601.');
if (Date.parse(fin) <= Date.parse(inicio)) throw new Error('RANGO_INVALIDO: el fin va despues del inicio.');

const opId = String(inp.operation_id || inp.proposal_id || '').trim();
const alfabeto = 'abcdefghijkmnpqrstuvwxyz23456789';
let token = '';
for (let i = 0; i < 20; i += 1) token += alfabeto[Math.floor(Math.random() * alfabeto.length)];
const nombre = String(inp.nombre_contacto || 'Lead IA360').trim();
const numero = String(inp.numero_contacto || '').replace(/[^0-9]/g, '');
const titulo = String(inp.titulo || '').trim() || ('Reunión IA360 - ' + nombre);

return [{
  json: {
    token,
    start: inicio,
    end: fin,
    summary: titulo,
    contact: { contactName: nombre, contactNumber: numero },
    operation_id: opId || null
  }
}];

const prep = $('Preparar Reserva').first().json;
const reserva = $('Reservar Calendar y Zoom').first().json || {};
const dbRow = $input.first() ? $input.first().json : null;

const eventId = reserva.calendarEventId;
const persisted = Boolean(dbRow && dbRow.token && dbRow.event_id);
const verified = Boolean(reserva.ok === true && eventId && persisted && reserva.verified === true);

if (!verified) {
  return [{
    json: {
      ok: false,
      verified: false,
      state: persisted ? 'no_agendada' : 'incierta',
      estado: 'incierta',
      error: 'Inconsistencia en reserva: el evento o la persistencia de enlace no pudo ser verificada.',
      motivo: 'Verificación de persistencia falló tras llamada a proveedor'
    }
  }];
}

const tz = 'America/Mexico_City';
const inicioFmt = new Intl.DateTimeFormat('es-MX', { timeZone: tz, dateStyle: 'full', timeStyle: 'short' }).format(new Date(prep.start));
const finFmt = new Intl.DateTimeFormat('es-MX', { timeZone: tz, timeStyle: 'short' }).format(new Date(prep.end));

return [{
  json: {
    ok: true,
    verified: true,
    state: 'agendada',
    estado: 'agendada',
    token: dbRow.token,
    enlace_estable: 'https://wa.geekstudio.dev/api/r/' + dbRow.token,
    evento_id: eventId,
    calendar_event_id: eventId,
    zoom_meeting_id: reserva.zoomMeetingId || null,
    zoom_join_url: reserva.zoomJoinUrl || null,
    start_utc: prep.start,
    end_utc: prep.end,
    inicio_local: inicioFmt,
    fin_local: finFmt,
    titulo: prep.summary,
    resumen: `${prep.summary} agendada para el ${inicioFmt} a ${finFmt} (hora CDMX). Enlace: https://wa.geekstudio.dev/api/r/${dbRow.token}`
  }
}];

const raw = $input.first() ? ($input.first().json || {}) : {};
const detalle = raw.error || raw.message || raw.motivo || JSON.stringify(raw).slice(0, 300);

return [{
  json: {
    ok: false,
    verified: false,
    state: 'no_agendada',
    estado: 'no_agendada',
    error: detalle || 'El webhook de reserva no devolvió un evento de calendario válido.',
    motivo: detalle || 'Falla en creación de cita con proveedor'
  }
}];
